routes = [{"method": method.upper(), "url": url, "file": implementation_path(file)} for file in route_files for method, _, url in re.findall(r"app\.(get|post|put|patch|delete)\(\s*(['\"])(.*?)\2", (BACKEND / "src/modules/administration" / file).read_text())]
