source_definitions = []
for name in ("stores/views.py", "users/views.py", "core/views.py", "core/datatables/store_products_datatable.py", "core/datatables/special_permition_datatable.py", "core/datatables/gift_card_datatable.py", "helpers/task_helpers.py"):
    data=(SOURCE/name).read_bytes()
    if hashlib.sha256(data).hexdigest()!=source_hashes.get(name):
        raise ValueError(f"Source evidence changed since the recorded baseline: {name}")
    tree = ast.parse(data.decode())
    selected = {item for _, names, _, _ in FEATURES for item in names}
    for node in tree.body:
        if isinstance(node, (ast.ClassDef, ast.FunctionDef)) and node.name in selected:
            source_definitions.append({"file": name, "line": node.lineno, "name": node.name})

